import fs from "node:fs";
import path from "node:path";
import { OAUTH_FETCHED_ON } from "@/data/oauthVendors";
import { WEBHOOKS_FETCHED_ON } from "@/data/webhookPayloads";

/**
 * What /collections and /cheat-sheets say about their files
 * (ops/VIRAL-20-2026-11-06.md items 12 and 13), shared with their markdown
 * mirrors. The files are generated by scripts/build-collections.mjs and
 * scripts/build-cheat-sheets.mjs; these pages read the index each script
 * writes, so the page lists exactly what was published.
 */

function readPublicJson<T>(rel: string, hint: string): T {
  const file = path.join(process.cwd(), "public", rel);
  if (!fs.existsSync(file)) throw new Error(`public/${rel} is missing — run ${hint} before building.`);
  return JSON.parse(fs.readFileSync(file, "utf8")) as T;
}

/* ── /collections ──────────────────────────────────────────────────────── */

export const COLLECTIONS_PATH = "/collections";
export const COLLECTIONS_H1 = "Postman and Bruno collections for wearable APIs";
export const COLLECTIONS_TITLE = "Wearable API Postman & Bruno Collections";
export const COLLECTIONS_DESCRIPTION =
  "Import-ready Postman (v2.1) and Bruno collections for Oura, WHOOP, Strava, Polar, Withings, Wahoo, Dexcom, Suunto, Google Health and Terra. No secrets.";

export type CollectionIndexEntry = {
  id: string;
  name: string;
  folders: { name: string; requests: string[] }[];
  variables: string[];
  postman: string;
  bruno: string;
  postmanBytes: number;
  brunoBytes: number;
  brunoFiles: string[];
};

export function collectionIndex(): CollectionIndexEntry[] {
  return readPublicJson<{ collections: CollectionIndexEntry[] }>("collections/index.json", "node scripts/build-collections.mjs").collections;
}

/** The newest date the vendor pages behind the collections were read. */
export function collectionsAsOf(): string {
  return [OAUTH_FETCHED_ON, WEBHOOKS_FETCHED_ON].sort().at(-1)!;
}

export function collectionsCapsule(): string {
  const c = collectionIndex();
  const oauth = c.filter((x) => x.folders.some((f) => f.name === "OAuth 2.0")).length;
  const hooks = c.filter((x) => x.folders.some((f) => f.name === "Webhook samples")).length;
  const requests = c.reduce((n, x) => n + x.folders.reduce((m, f) => m + f.requests.length, 0), 0);
  return (
    `Download a Postman collection (Collection Format v2.1.0) or a Bruno collection folder for ${c.length} wearable and health APIs: ` +
    `${oauth} with the vendor's OAuth 2.0 authorization URL, code-for-token exchange and, where documented, refresh request, using {{client_id}}-style variables, ` +
    `and ${hooks} with the vendor's documented webhook examples posted to {{local_url}}, ${requests} requests in all. ` +
    `They are generated from the same vendor quotes as the OAuth playground and the webhook payload library (read ${collectionsAsOf()}), and ship no secrets: client_secret and every token are empty variables you fill in your own environment.`
  );
}

