/* ── /cheat-sheets ─────────────────────────────────────────────────────── */

export const CHEATSHEETS_PATH = "/cheat-sheets";
export const CHEATSHEETS_H1 = "Printable cheat sheets: HealthKit, Health Connect, pose keypoints";
export const CHEATSHEETS_TITLE = "Cheat Sheets: HealthKit, Health Connect, Pose Keypoints";
export const CHEATSHEETS_DESCRIPTION =
  "One-page PDF and PNG cheat sheets: HealthKit identifiers and permission errors, Health Connect records and the 30-day window, COCO-17 and BlazePose-33.";

export type CheatSheet = {
  slug: string;
  title: string;
  asOf: string;
  pdf: string;
  png: string;
  pdfBytes: number;
  pngBytes: number;
  pngWidth: number;
  pngHeight: number;
};

export function cheatSheets(): CheatSheet[] {
  return readPublicJson<{ sheets: CheatSheet[] }>("cheat-sheets/manifest.json", "node scripts/build-cheat-sheets.mjs").sheets;
}

