export function cheatSheetsAsOf(): string {
  return cheatSheets()
    .map((s) => s.asOf)
    .sort()
    .at(-1)!;
}

export function cheatSheetsCapsule(): string {
  const s = cheatSheets();
  return (
    `${s.length} one-page A4 cheat sheets, each as a PDF to print and a PNG to pin or post: HealthKit (common identifiers, units and permission errors), ` +
    `Health Connect (record types, read permissions and the 30-day history window) and pose keypoints (COCO 17 and BlazePose 33 index maps). ` +
    `A script prints them with a headless Chromium from the site's generated copies of Apple's, Google's and the model authors' sources, so each line is copied, not retyped; the newest source was read ${cheatSheetsAsOf()}. Free under CC BY 4.0.`
  );
}

